package com.wang.controller;

import com.wang.popj.Result;
import com.wang.popj.User;
import com.wang.service.UserService;
import com.wang.utils.JwtUtil;
import com.wang.utils.Md5Util;
import com.wang.utils.ThreadLocalUtil;
import jakarta.validation.constraints.Pattern;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping(value = "/user")
@Validated
public class UserController {
    @Autowired
    private UserService userService;

    /**
     * 注册接口
     *
     * @param username 用户名
     * @param password 密码
     */
    @RequestMapping(value = "/register")
    public Result register(@Pattern(regexp = "^\\S{5,16}$") String username, @Pattern(regexp = "^\\S{5,16}$") String password) {
        //查询用户是否存在
        User user = userService.findByUsername(username);
        if (user == null) {
            //保存用户
            userService.register(username, password);
            return Result.success();
        } else {
            //占用用户名
            return Result.error("用户名已存在");
        }
    }

    /**
     * 登录接口
     *
     * @param username 用户名
     * @param password 密码
     */
    @RequestMapping(value = "/login")
    public Result<String> login(@Pattern(regexp = "^\\S{5,16}$") String username, @Pattern(regexp = "^\\S{5,16}$") String password) {
        //查询用户是否存在
        User user = userService.findByUsername(username);
        if (user == null) {
            //用户名不存在
            return Result.error("用户名不存在");
        }
        //判断密码是否正确
        if (Md5Util.getMD5String(password).equals(user.getPassword())) {
            Map<String, Object> jw = new HashMap<>();
            jw.put("id", user.getId());
            jw.put("username", user.getUsername());
            //生成token
            String token = JwtUtil.genToken(jw);
            return Result.success(token);
        }
        return Result.error("密码错误");
    }

    /**
     * 获取用户信息接口
     *
     *
     */
    @RequestMapping(value = "/info")
    public Result<User> info() {
        Map<String, Object> token = ThreadLocalUtil.get();
        System.out.println(token);
        String username = (String)token.get("username");
        User user =userService.findByUsername(username);
        return  Result.success(user);
    }

}

